import os
import subprocess
import json
from pathlib import Path

files = sorted([f for f in os.listdir('.') if f.endswith(('.pdf', '.pptx', '.docx'))])

categorization = {}

for file in files:
    categorization[file] = {
        'filename': file,
        'type': file.split('.')[-1],
        'content_snippet': '',
        'category': 'unknown'
    }

    try:
        if file.endswith('.pdf'):
            # Extract first 500 characters of text
            result = subprocess.run(['pdftotext', file, '-'], capture_output=True, text=True, timeout=5)
            text = result.stdout[:500] if result.stdout else ''
            categorization[file]['content_snippet'] = text
    except Exception as e:
        pass

# Print results for analysis
for file, info in categorization.items():
    print(f"\n{'='*60}")
    print(f"File: {file}")
    print(f"Type: {info['type']}")
    if info['content_snippet']:
        print(f"Content:\n{info['content_snippet'][:300]}")

